"use client";
import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { ArrowLeft, ChevronLeft, ChevronRight, MapPin, Phone, Star, Store } from "lucide-react";

type Vendor = { _id: string; name: string; category: string; description?: string; area?: string; location?: string; stallNumber?: string; phone?: string; contact?: string; shopImageUrl?: string; shopImages?: string[]; imageUrl?: string; rating?: number | null; reviewCount?: number };
type Review = { _id: string; reviewerName: string; comment: string; ratings: Record<string, number>; createdAt: string };
const foodCriteria = [{key:"taste",label:"Taste"},{key:"hygiene",label:"Hygiene & cleanliness"},{key:"politeness",label:"Politeness of vendor"},{key:"valueForMoney",label:"Value for money"},{key:"portion",label:"Portion size"},{key:"service",label:"Service speed"}];
const shoppingCriteria = [{key:"productQuality",label:"Product quality"},{key:"variety",label:"Product variety"},{key:"priceFairness",label:"Price fairness"},{key:"politeness",label:"Politeness of vendor"},{key:"valueForMoney",label:"Value for money"},{key:"trustworthiness",label:"Trustworthiness"}];
const attractionCriteria = [{key:"safety",label:"Safety"},{key:"fun",label:"Enjoyment"},{key:"valueForMoney",label:"Value for money"},{key:"staffPoliteness",label:"Staff politeness"},{key:"cleanliness",label:"Cleanliness"}];
const inputClass = "mt-1 w-full rounded-xl border border-[#EAD9BD] bg-white px-3 py-3 text-sm outline-none focus:border-[#9B3540]";
export default function VendorReviewClient({vendorId}:{vendorId:string}) {
  const [vendor,setVendor]=useState<Vendor|null>(null); const [photoIndex,setPhotoIndex]=useState(0); const [reviews,setReviews]=useState<Review[]>([]); const [averages,setAverages]=useState<Record<string,number>>({}); const [loading,setLoading]=useState(true); const [error,setError]=useState(""); const [message,setMessage]=useState(""); const [busy,setBusy]=useState(false); const [name,setName]=useState(""); const [comment,setComment]=useState(""); const [ratings,setRatings]=useState<Record<string,number>>({});
  const criteria = vendor?.category === "Food & Drinks" ? foodCriteria : vendor?.category === "Shopping" ? shoppingCriteria : attractionCriteria;
  const loadReviews=useCallback(async()=>{const response=await fetch(`/api/stalls/${vendorId}/reviews`,{cache:"no-store"});const body=await response.json();if(response.ok){setReviews(body.data||[]);setAverages(body.averages||{});}},[vendorId]);
  useEffect(()=>{let active=true;(async()=>{try{const response=await fetch("/api/stalls?limit=200",{cache:"no-store"});const body=await response.json();if(!response.ok)throw new Error(body.error||"Could not load vendor.");const found=(body.data||[]).find((item:Vendor)=>item._id===vendorId);if(!found)throw new Error("This vendor is not published or could not be found.");if(active)setVendor(found);const r=await fetch(`/api/stalls/${vendorId}/reviews`,{cache:"no-store"});const rb=await r.json();if(r.ok&&active){setReviews(rb.data||[]);setAverages(rb.averages||{});}}catch(e){if(active)setError(e instanceof Error?e.message:"Could not load this vendor.");}finally{if(active)setLoading(false);}})();return()=>{active=false}},[vendorId]);
  async function submit(event:React.FormEvent){event.preventDefault();setMessage("");if(criteria.some(item=>!ratings[item.key])){setMessage("Please rate every factor before submitting.");return;}setBusy(true);try{const response=await fetch(`/api/stalls/${vendorId}/reviews`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({reviewerName:name,comment,ratings})});const body=await response.json();if(!response.ok)throw new Error(body.error||"Review submission failed.");setMessage("Thank you! Your review has been submitted.");setName("");setComment("");setRatings({});await loadReviews();}catch(e){setMessage(e instanceof Error?e.message:"Review submission failed.");}finally{setBusy(false)}}
  return <main className="min-h-screen bg-[#FFF9EE] px-5 py-8 text-[#321B1A]"><div className="mx-auto max-w-4xl"><Link href="/#stalls" className="inline-flex items-center gap-2 text-sm font-bold text-[#8A2631]"><ArrowLeft className="h-4 w-4"/> Back to stalls</Link>{loading?<p className="py-16 text-center">Loading vendor…</p>:error?<div role="alert" className="mt-8 rounded-2xl border border-red-200 bg-white p-6 text-red-800">{error}</div>:vendor&&<><article className="mt-5 overflow-hidden rounded-3xl border border-[#EAD9BD] bg-white"><div className="relative h-64 bg-[#F8EEDC] sm:h-80">{(() => { const photos = (vendor.shopImages?.length ? vendor.shopImages : [vendor.shopImageUrl || vendor.imageUrl || ""]).filter(Boolean); return photos.length ? <><img src={photos[Math.min(photoIndex, photos.length - 1)]} alt={`${vendor.name} shop photo ${Math.min(photoIndex, photos.length - 1) + 1}`} className="h-full w-full object-cover transition-opacity duration-300"/>{photos.length > 1 && <><button type="button" onClick={() => setPhotoIndex(index => (index - 1 + photos.length) % photos.length)} aria-label="Previous shop photo" className="absolute left-3 top-1/2 flex h-10 w-10 -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-[#571E24] shadow hover:bg-white"><ChevronLeft className="h-6 w-6"/></button><button type="button" onClick={() => setPhotoIndex(index => (index + 1) % photos.length)} aria-label="Next shop photo" className="absolute right-3 top-1/2 flex h-10 w-10 -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-[#571E24] shadow hover:bg-white"><ChevronRight className="h-6 w-6"/></button><div className="absolute bottom-3 left-1/2 flex -translate-x-1/2 gap-2 rounded-full bg-black/35 px-3 py-2">{photos.map((_, index) => <button key={index} type="button" onClick={() => setPhotoIndex(index)} aria-label={`Show photo ${index + 1}`} className={`h-2.5 w-2.5 rounded-full ${index === photoIndex ? "bg-white" : "bg-white/50"}`}/>)}</div><span className="absolute right-3 top-3 rounded-full bg-black/50 px-2.5 py-1 text-xs font-bold text-white">{Math.min(photoIndex, photos.length - 1) + 1} / {photos.length}</span></>}</> : <div className="flex h-full items-center justify-center text-[#8A2631]"><Store className="h-16 w-16"/></div>; })()}</div><div className="p-6 sm:p-8"><p className="text-xs font-bold uppercase tracking-[0.2em] text-[#A36A2B]">{vendor.category}</p><h1 className="mt-2 text-3xl font-black text-[#571E24]">{vendor.name}</h1><div className="mt-2 inline-flex items-center gap-1 text-sm font-bold text-[#6E4B25]"><Star className="h-4 w-4 fill-amber-400 text-amber-500"/>{typeof vendor.rating === "number" ? vendor.rating.toFixed(1) : "New"}<span className="font-normal text-[#80675E]">{vendor.reviewCount ? `· ${vendor.reviewCount} ${vendor.reviewCount === 1 ? "review" : "reviews"}` : "· No reviews yet"}</span></div><p className="mt-3 text-sm leading-6 text-[#80675E]">{vendor.description||"Local mela vendor"}</p><div className="mt-5 flex flex-col gap-3 text-sm text-[#745448] sm:flex-row sm:flex-wrap">{(vendor.area||vendor.location)&&<span className="flex items-center gap-2"><MapPin className="h-4 w-4 text-[#8A2631]"/>{vendor.area||vendor.location}</span>}{(vendor.phone||vendor.contact)&&<a className="flex items-center gap-2 font-semibold text-[#8A2631]" href={`tel:${vendor.phone||vendor.contact}`}><Phone className="h-4 w-4"/>{vendor.phone||vendor.contact}</a>}{vendor.stallNumber&&<span>Stall {vendor.stallNumber}</span>}</div></div></article>
  <section className="mt-7 rounded-3xl border border-[#EAD9BD] bg-white p-6 sm:p-8"><h2 className="text-2xl font-black text-[#571E24]">Rate this vendor</h2><p className="mt-2 text-sm text-[#80675E]">Give 1 star for poor and 5 stars for excellent. Review factors match this vendor’s category.</p><form onSubmit={submit} className="mt-6 space-y-5"><label className="block text-sm font-semibold">Your name<input required minLength={2} maxLength={60} value={name} onChange={e=>setName(e.target.value)} className={inputClass} placeholder="Enter your name"/></label><div className="grid gap-4 sm:grid-cols-2">{criteria.map(item=><div key={item.key} className="rounded-xl bg-[#FFFAF1] p-4"><p className="text-sm font-semibold text-[#571E24]">{item.label}</p><div className="mt-2 flex items-center gap-1" role="group" aria-label={item.label}>{[1,2,3,4,5].map(value=><button key={value} type="button" onClick={()=>setRatings(current=>({...current,[item.key]:value}))} aria-label={`${value} stars for ${item.label}`} className="rounded p-1"><Star className={`h-6 w-6 ${Number(ratings[item.key]||0)>=value?"fill-amber-400 text-amber-500":"text-[#D8C9B3]"}`}/></button>)}<span className="ml-1 text-xs text-[#80675E]">{ratings[item.key]?`${ratings[item.key]}/5`:"Choose"}</span></div></div>)}</div><label className="block text-sm font-semibold">Comment (optional)<textarea maxLength={1000} rows={4} value={comment} onChange={e=>setComment(e.target.value)} className={inputClass} placeholder="Share your experience respectfully…"/></label>{message&&<p role="status" className="rounded-xl bg-[#FFF2D8] p-3 text-sm text-[#571E24]">{message}</p>}<button disabled={busy} className="rounded-xl bg-[#811D2B] px-6 py-3 font-bold text-white disabled:opacity-60">{busy?"Submitting…":"Submit review"}</button></form></section>
  <section className="mt-7 rounded-3xl border border-[#EAD9BD] bg-white p-6 sm:p-8"><h2 className="text-2xl font-black text-[#571E24]">Community reviews <span className="text-base font-semibold text-[#80675E]">({reviews.length})</span></h2>{Object.keys(averages).length>0&&<div className="mt-4 grid gap-3 sm:grid-cols-2">{criteria.filter(c=>averages[c.key]!==undefined).map(c=><div key={c.key} className="flex justify-between rounded-xl bg-[#FFFAF1] p-3 text-sm"><span>{c.label}</span><strong className="flex items-center gap-1 text-[#8A2631]"><Star className="h-4 w-4 fill-amber-400 text-amber-500"/>{averages[c.key]}/5</strong></div>)}</div>}{reviews.length===0?<p className="mt-4 text-sm text-[#80675E]">No reviews yet. Be the first to share your experience.</p>:<div className="mt-5 space-y-4">{reviews.map(review=><article key={review._id} className="border-t border-[#F0E4D0] pt-4"><div className="flex flex-wrap justify-between gap-2"><strong className="text-[#571E24]">{review.reviewerName}</strong><span className="text-xs text-[#80675E]">{new Date(review.createdAt).toLocaleDateString()}</span></div>{review.comment&&<p className="mt-2 text-sm leading-6 text-[#80675E]">{review.comment}</p>}<div className="mt-3 flex flex-wrap gap-2">{criteria.filter(c=>review.ratings?.[c.key]).map(c=><span key={c.key} className="rounded-full bg-[#F7EBD7] px-3 py-1 text-xs">{c.label}: {review.ratings[c.key]}/5</span>)}</div></article>)}</div>}</section></>}</div></main>;
}
